  gemini: DEFAULT_BRIDGE_URL,
  antigravity: DEFAULT_BRIDGE_URL,
  pi: DEFAULT_BRIDGE_URL,
  grok: DEFAULT_BRIDGE_URL,
  kimi: DEFAULT_BRIDGE_URL,
  moonshot: DEFAULT_BRIDGE_URL,
