  deafenBtn.onclick = () => { AGENT_MUTED = !AGENT_MUTED; try { localStorage.setItem("cmcp.muteAgents", AGENT_MUTED ? "1" : "0"); } catch {} reflectFeedGates(); };
  let _blindAckPending = null;
  window.addEventListener("cmcp:set-content-mode-ack", () => {
    if (_blindAckPending) { clearTimeout(_blindAckPending); _blindAckPending = null; }
  });
  blindBtn.onclick = () => {
    AGENT_BLIND = !AGENT_BLIND;
    try { localStorage.setItem("cmcp.blindAgents", AGENT_BLIND ? "1" : "0"); } catch {}
    reflectFeedGates();
    // Issue #90: Blind must also gate the comfyui MCP's image tools
    // (get_image action:"get"/"view" return pixels straight from /view). Tell the
    // orchestrator so it respawns this tab's tool server with the blind env —
    // without this the toggle only covered the panel's own image channel.
    // An OLD orchestrator has no handler and never acks — warn so the user
    // knows only the legacy panel-feed gating applies (codex-review F4). A
    // lost frame (socket drop) self-heals on the next hello, which re-seeds
    // blind and respawns on change.
    if (_blindAckPending) { clearTimeout(_blindAckPending); _blindAckPending = null; }
    let sent = false;
    // #640 — no explicit tab_id: sendFrame stamps the established BRIDGE ROUTE
    // (and refuses when there is none). An explicit one here would have won the
    // spread and put the path-only workflow handle back on the wire.
    try { sent = client?.sendFrame?.({ type: "set_content_mode", blind: AGENT_BLIND }) !== false; } catch {}
    if (sent) {
      _blindAckPending = setTimeout(() => {
        _blindAckPending = null;
        appendSystem(
          "⚠️ The orchestrator didn't acknowledge the Blind change — it may predate v0.42.0, where Blind only gates the panel's own image feed (the agent's image tools are NOT gated). Update comfyui-mcp for full enforcement.",
        );
      }, 6000);
    }
  };
  ring.style.cursor = "pointer"; ring.onclick = deafenBtn.onclick; // clicking the ring toggles deafen
  reflectFeedGates();

  // Unified side panel (issue #124): ONE tabbed overlay hosting Civitai / Apps /
  // Training / Local-RunPod. openSidePanelTab opens it (or switches tab if it is
  // already open); the four openX wrappers + toolbar buttons all route through it.
  // Mark: Civitai's hexagon-C, monochrome via currentColor (no brand gradients,
  // no event attrs — keeps the registry's SVG YARA gate happy).
  let _sidePanelHandle = null;
  function sidePanelCtx() {
    return {
      api,
      root,
      // Agent-drive side-dock geometry/observation (pane may be docked L or R).
      dockGeometry: panelDockGeometry,
      watchDock: panelWatchDock,
      callTool: (t, a, o) => liveBridgeClient?.callTool(t, a, o),
      sendUserMessage: (t, c, i) => liveBridgeClient?.sendUserMessage(t, c, i),
      uploadBlobToInput,
      bringChatForward: () => { try { openSidebarTab(); } catch {} },
      isMuted: () => AGENT_MUTED,
      marked,
      DOMPurify,
      // Apps tab: live canvas app; Local tab: honest host + pod status frames.
      getApp: () => app,
      getRunpodTarget: () => _comfyuiTarget,
      // Apps pod runs: transfer image inputs through the bridge's upload_media
      // handler → the CONNECTED ComfyUI (the pod when on one), not the local
      // /upload/image (#125).
      uploadMedia: (b, n) => liveBridgeClient?.uploadMedia(b, n),
      getStatus: () => _runpodStatus,
      getTarget: () => _comfyuiTarget,
      openUrl: (u) => { try { window.open(u, "_blank", "noopener"); } catch {} },
      // Canvas access for "load workflow onto canvas" (Civitai tab): dirty check
      // for the confirm-overwrite prompt, then the SAME undoable path the bridge's
      // graph_load command takes (snapshot → await loadGraphData → checkState, so
      // one load = one Ctrl+Z step). Dirty check fails CLOSED: when the workflow
      // state can't be read (older frontend, missing service, throw), report dirty
      // so the caller confirms instead of silently clobbering an unsaved canvas.
      graphIsDirty: () => {
        try {
          const wf = app?.extensionManager?.workflow?.activeWorkflow;
          if (!wf || typeof wf.isModified !== "boolean") return true; // unknown → confirm
          return wf.isModified;
        } catch { return true; }
      },
      loadGraph: async (graph) => {
        const result = await GRAPH_TOOL_EXECUTORS.graph_load({ graph });
        try {
          app.extensionManager?.workflow?.activeWorkflow?.changeTracker?.checkState?.();
        } catch { /* tracker unavailable (older frontend) — undo stays best-effort */ }
        return result;
      },
    };
  }
  // The four toolbar buttons ARE the tab bar: reflect the open surface with a
  // themed toggled state (cleared on close). The buttons are const-declared below,
  // but this only runs at tab-change time, by which point they're initialized.
  function setActiveToolbarTab(key) {
    const map = { civitai: civitaiBtn, apps: appsBtn, training: trainingBtn, local: runpodBtn };
    for (const [k, btn] of Object.entries(map)) {
      if (btn) btn.classList.toggle("cmcp-toolbtn-active", k === key);
    }
  }
  /** Open the unified side panel on `tab`, or switch to it if already open. */
  function openSidePanelTab(tab, { tabOpts, dock = true } = {}) {
    if (_sidePanelHandle?.isOpen?.()) {
      try { _sidePanelHandle.switchTab(tab, tabOpts); } catch { /* stale */ }
      return _sidePanelHandle;
    }
    const handle = openSidePanel(sidePanelCtx(), {
      tab,
      dock,
      ...(tabOpts ? { tabOpts: { [tab]: tabOpts } } : {}),
      // The toolbar buttons are the tabs — highlight the active one on every switch.
      onTabChange: setActiveToolbarTab,
      // Null the stored handle whenever the panel closes (✕, Escape, backdrop) so
      // post-open drive cmds get an honest "not open" error; clear the toolbar too.
      onClose: () => { if (_sidePanelHandle === handle) _sidePanelHandle = null; setActiveToolbarTab(null); },
    });
    _sidePanelHandle = handle;
    return handle;
  }
  // Toolbar-click toggle: clicking the ALREADY-active surface closes the panel.
  // Scoped to the toolbar buttons only — the agent open path (openCivitai etc.)
